import { redirect, notFound } from 'next/navigation'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { ClientProfileHero } from '@/components/clients/ClientProfileHero'
import { ClientTabNav } from '@/components/clients/ClientTabNav'
import { fetchClientHealthSummary } from '@/lib/clients/health'
import { isPinned as checkIsPinned } from '@/lib/pinned-items/pinned'
import type { Database } from '@/lib/supabase/types'

type ClientTag = Database['public']['Tables']['client_tags']['Row']

interface Props {
  children: React.ReactNode
  params: Promise<{ id: string }>
}

export default async function ClientDetailLayout({ children, params }: Props) {
  const { id } = await params

  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Single parallel fetch for above-fold hero + counts (LCP target < 2s)
  const [clientResult, tagsResult, nextBookingResult] = await Promise.all([
    supabase
      .from('clients')
      .select('id, first_name, last_name, email, phone, tags, total_spent_cents, total_sessions, last_visit_at, no_show_count, created_at, archived_at, preferred_contact, lifetime_value_cents, loyalty_points, cancellation_count, avg_session_value_cents, instagram_handle, tiktok_handle, website_url, is_banned, banned_reason, banned_at, banned_by')
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .single(),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId),
    supabase
      .from('bookings')
      .select('scheduled_at')
      .eq('client_id', id)
      .eq('studio_id', auth.studioId)
      .in('status', ['pending', 'confirmed'])
      .gte('scheduled_at', new Date().toISOString())
      .order('scheduled_at', { ascending: true })
      .limit(1),
  ])

  if (clientResult.error || !clientResult.data) {
    if (clientResult.error?.code === 'PGRST116') notFound()
    redirect('/clients')
  }

  const client = clientResult.data
  const tagLibrary = (tagsResult.data ?? []) as ClientTag[]
  const nextBookingDate = nextBookingResult.data?.[0]?.scheduled_at ?? null

  // S22: pre-compute pinned status for this client
  const clientIsPinned = await checkIsPinned(auth.user.authId, auth.studioId, 'client', id)

  // Fetch health summary in parallel with counts
  const [photoCount, noteCount, fileCount, commCount, healthSummary] = await Promise.all([
    supabase
      .from('booking_photos')
      .select('id', { count: 'exact', head: true })
      .eq('client_id', id)
      .eq('studio_id', auth.studioId),
    supabase
      .from('client_notes')
      .select('id', { count: 'exact', head: true })
      .eq('client_id', id)
      .eq('studio_id', auth.studioId),
    supabase
      .from('client_files')
      .select('id', { count: 'exact', head: true })
      .eq('client_id', id)
      .eq('studio_id', auth.studioId),
    supabase
      .from('client_communications')
      .select('id', { count: 'exact', head: true })
      .eq('client_id', id)
      .eq('studio_id', auth.studioId),
    fetchClientHealthSummary(supabase, id, auth.studioId),
  ])

  const counts = {
    photos: photoCount.count ?? 0,
    notes: noteCount.count ?? 0,
    files: fileCount.count ?? 0,
    comms: commCount.count ?? 0,
  }

  // Resolve tag names
  const resolvedTags = (client.tags ?? [])
    .map((slug) => tagLibrary.find((t) => t.id === slug || t.name === slug))
    .filter((t): t is ClientTag => Boolean(t))

  return (
    <div className="flex flex-col gap-4 p-4 lg:p-6">
      {/* Breadcrumb now rendered centrally by AppHeader via resolveDynamicLabels (S23).
          Local breadcrumb removed — single source of truth. */}

      {/* Hero */}
      <ClientProfileHero
        client={client as Parameters<typeof ClientProfileHero>[0]['client']}
        tags={resolvedTags as Parameters<typeof ClientProfileHero>[0]['tags']}
        healthSummary={healthSummary}
        nextBookingDate={nextBookingDate}
        canBan={auth.role === 'owner' || auth.role === 'admin'}
        isPinned={clientIsPinned}
        studioId={auth.studioId}
      />

      {/* Tab nav — sticky below header */}
      <div className="sticky top-14 z-20 bg-background pt-1 pb-0 -mx-4 px-4 lg:-mx-6 lg:px-6 border-b border-border/40">
        <ClientTabNav clientId={id} counts={counts} />
      </div>

      {/* Tab content */}
      <div className="pt-2">
        {children}
      </div>
    </div>
  )
}

